<template>
  <div class="mc">
    <div class="mc-accent-bar" :style="{ background: theme.bar }"></div>

    <!-- Шапка -->
    <div class="mc-top">
      <div class="mc-titles">
        <div class="mc-title">{{ $t(cfg.titleKey) }}</div>
        <div v-if="subtitle" class="mc-sub">{{ subtitle }}</div>
      </div>
      <div class="mc-top-right">
        <div
            class="mc-pct-badge"
            :style="{ background: theme.factBg, color: theme.pctColor, border: `1px solid ${theme.factBorder}` }"
        >
          {{ fulfillment }}%
        </div>
        <!-- Кнопка тенденции -->
        <button
            v-if="allData.length > 0"
            class="mc-trend-btn"
            :title="$t('trend.button')"
            @click="showTrend = true"
        >
          <v-icon size="14">mdi-chart-timeline-variant</v-icon>
        </button>
      </div>
    </div>

    <!-- Тело карточки -->
    <div class="mc-body">
      <div class="rw">
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" width="100" height="100">
          <defs>
            <linearGradient :id="gradientId" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" :stop-color="theme.strokeLight"/>
              <stop offset="100%" :stop-color="theme.strokeDark"/>
            </linearGradient>
          </defs>
          <circle cx="50" cy="50" r="44" fill="none" :stroke="theme.track" stroke-width="8"/>
          <circle
              cx="50" cy="50" r="44"
              fill="none"
              :stroke="`url(#${gradientId})`"
              stroke-width="8"
              stroke-linecap="round"
              :stroke-dasharray="circumference"
              :stroke-dashoffset="dashOffset"
              transform="rotate(-90 50 50)"
              class="ring-progress"
          />
        </svg>
        <div class="ring-center">
          <span class="ring-pct" :style="{ color: theme.pctColor }">{{ fulfillment }}%</span>
          <span class="ring-label">{{ $t('common.fulfilled') }}</span>
        </div>
      </div>

      <div class="metrics">
        <div class="metric-row plan-row">
          <span class="metric-label">{{ $t('common.plan') }}</span>
          <span class="metric-value">{{ fmt(plan, cfg.fmt) }}</span>
        </div>
        <div
            class="metric-row"
            :style="{ background: theme.factBg, border: `1px solid ${theme.factBorder}` }"
        >
          <span class="metric-label">{{ $t('common.fact') }}</span>
          <span class="metric-value" :style="{ color: theme.pctColor }">{{ fmt(fact, cfg.fmt) }}</span>
        </div>
        <div class="metric-divider"></div>
        <div class="metric-row-ly">
          <span class="metric-label-ly">{{ $t(cfg.pastKey) }}</span>
          <span class="metric-value-ly">{{ fmt(past, cfg.fmtPast) }}</span>
        </div>
      </div>
    </div>

    <div class="mc-footer">
      <span v-if="cfg.yoy" class="yoy-badge" :style="yoyStyle">{{ yoyLabel }}</span>
    </div>

    <!-- ── Попап тенденции ───────────────────────────── -->
    <v-dialog v-model="showTrend" :max-width="trendChartWidth" @after-leave="destroyTrendChart">
      <div class="trend-modal">

        <!-- Шапка попапа -->
        <div class="trend-modal-header" :style="{ background: theme.bar }">
          <div class="trend-modal-title">
            <v-icon size="18" color="white" style="margin-right:8px">mdi-chart-timeline-variant</v-icon>
            {{ $t(cfg.titleKey) }} — {{ $t('trend.title') }}
          </div>
          <button class="trend-close-btn" @click="showTrend = false">
            <v-icon size="18" color="white">mdi-close</v-icon>
          </button>
        </div>

        <!-- Легенда -->
        <div class="trend-legend">
          <div class="trend-leg-item">
            <span class="trend-leg-line" :style="{ background: theme.strokeDark }"></span>
            {{ $t('common.fact') }}
          </div>
          <div class="trend-leg-item">
            <span class="trend-leg-line trend-leg-line--dashed"></span>
            {{ $t('common.plan') }}
          </div>
        </div>

        <!-- График -->
        <div class="trend-chart-wrap" :style="{ height: trendChartHeight }">
          <canvas ref="trendCanvas"></canvas>
        </div>

        <!-- Пустые данные -->
        <div v-if="!trendData.labels.length" class="trend-no-data">
          {{ $t('trend.noData') }}
        </div>

      </div>
    </v-dialog>

  </div>
</template>

<script>
import {markRaw} from 'vue'
import {Chart, registerables} from 'chart.js'
import {dataStore} from '@/operations/requests'

Chart.register(...registerables)

const METRICS = {
  revenue: {
    titleKey: 'metrics.revenue',
    f: 'products_f',
    p: 'products_p',
    past: 'products_past',
    pastKey: 'common.lastYear',
    yoy: true,
    fmt: 'locale',
    fmtPast: 'amount'
  },
  services: {
    titleKey: 'metrics.services',
    f: 'services_f',
    p: 'services_p',
    past: 'services_past',
    pastKey: 'common.lastYear',
    yoy: true,
    fmt: 'locale',
    fmtPast: 'amount'
  },
  trafic: {
    titleKey: 'metrics.trafic',
    f: 'trafic_f',
    p: 'trafic_p',
    past: 'trafic_past',
    pastKey: 'common.lastYear',
    yoy: true,
    fmt: 'locale',
    fmtPast: 'locale'
  },
  conversion: {
    titleKey: 'metrics.conversion',
    f: 'conver_f',
    p: 'conver_p',
    past: 'conver_past',
    pastKey: 'common.lastYear',
    yoy: true,
    fmt: 'amount',
    fmtPast: 'amount'
  },
  check: {
    titleKey: 'metrics.check',
    f: 'check_f',
    p: 'check_p',
    past: 'check_past',
    pastKey: 'common.lastYear',
    yoy: true,
    fmt: 'locale',
    fmtPast: 'locale'
  },
  count: {
    titleKey: 'metrics.count',
    f: 'count_f',
    p: 'count_p',
    past: 'count_past',
    pastKey: 'common.lastYear',
    yoy: true,
    fmt: 'amount',
    fmtPast: 'amount'
  },
  credit: {
    titleKey: 'metrics.credit',
    f: 'credit_f',
    p: 'credit_p',
    past: 'credit_sum',
    pastKey: 'common.sum',
    yoy: false,
    fmt: 'amount',
    fmtPast: 'locale'
  },
}

export default {
  name: 'MetricCard',
  props: {
    metricKey: {type: String, required: true},
    selectedDate: {type: String, default: ''},
    rowData: {type: Object, default: null},
    allData: {type: Array, default: () => []}, // все периоды для тенденции
  },
  data() {
    return {
      gradientId: 'ring-' + Math.random().toString(36).slice(2, 7),
      subtitle: '',
      fact: 0,
      plan: 0,
      past: 0,
      circumference: 2 * Math.PI * 44,
      animated: false,
      showTrend: false,
    }
  },
  created() {
    this._trendChart = null
  },
  computed: {
    cfg() {
      return METRICS[this.metricKey] || METRICS.revenue
    },

    fulfillment() {
      if (!this.plan) return 0
      return Math.round((this.fact / this.plan) * 1000) / 10
    },

    dashOffset() {
      if (!this.animated) return this.circumference
      return this.circumference * (1 - Math.min(this.fulfillment / 100, 1))
    },

    theme() {
      if (this.fulfillment >= 100) return {
        bar: 'linear-gradient(90deg,#22c55e,#4ade80)',
        strokeDark: '#16a34a', strokeLight: '#4ade80',
        track: '#dcfce7', pctColor: '#16a34a',
        factBg: '#f0fdf4', factBorder: '#bbf7d0',
      }
      if (this.fulfillment >= 85) return {
        bar: 'linear-gradient(90deg,#f59e0b,#fcd34d)',
        strokeDark: '#d97706', strokeLight: '#fde68a',
        track: '#fef3c7', pctColor: '#d97706',
        factBg: '#fffbeb', factBorder: '#fde68a',
      }
      return {
        bar: 'linear-gradient(90deg,#ef4444,#fca5a5)',
        strokeDark: '#dc2626', strokeLight: '#fca5a5',
        track: '#fee2e2', pctColor: '#dc2626',
        factBg: '#fff5f5', factBorder: '#fecaca',
      }
    },

    yoyChange() {
      if (!this.past) return null
      return Math.round(((this.fact - this.past) / this.past) * 100)
    },

    yoyLabel() {
      if (this.yoyChange === null) return '—'
      return (this.yoyChange > 0 ? '▲ +' : '▼ ') + this.yoyChange + '% ' + this.$t('common.toLastYear')
    },

    yoyStyle() {
      if (this.yoyChange === null) return 'background:#f3f4f6;color:#9ba3b8'
      return this.yoyChange > 0
          ? 'background:#dcfce7;color:#15803d;border:1px solid #bbf7d0'
          : 'background:#fee2e2;color:#b91c1c;border:1px solid #fecaca'
    },

    // Ширина: 620px база, +50px за каждый период сверх 5
    trendChartWidth() {
      const n = this.trendData.labels.length
      return Math.max(620, 620 + Math.max(0, n - 5) * 50)
    },

    // Высота чарта: 280px база, +30px за каждый период сверх 5
    trendChartHeight() {
      const n = this.trendData.labels.length
      return Math.max(280, 280 + Math.max(0, n - 5) * 30) + 'px'
    },
    trendData() {
      if (!this.allData.length) return {labels: [], facts: [], plans: []}
      const sorted = [...this.allData]
      const c = this.cfg
      return {
        labels: sorted.map(r => r.time || ''),
        facts:  sorted.map(r => Number(r[c.f] ?? 0) || 0),
        plans:  sorted.map(r => Number(r[c.p] ?? 0) || 0),
      }
    },
  },
  mounted() {
    this.setData()
    requestAnimationFrame(() => {
      this.animated = true
    })
  },
  beforeUnmount() {
    this.destroyTrendChart()
  },
  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal && !this.rowData) this.refresh()
    },
    rowData: {
      handler(val) {
        if (val) this.refresh()
      },
      immediate: false,
    },
    showTrend(val) {
      if (val) this.$nextTick(() => this.initTrendChart())
    },
  },
  methods: {
    refresh() {
      this.animated = false
      setTimeout(() => {
        this.setData()
        requestAnimationFrame(() => {
          this.animated = true
        })
      }, 500)
    },

    setData() {
      const row = this.rowData || (() => {
        const payload = dataStore.getCompanyData()
        if (!payload) return null
        return payload.find(item => item.time === this.selectedDate) || null
      })()
      if (!row) return
      const c = this.cfg
      this.subtitle = row.time
      this.fact = Number(row[c.f])    || 0
      this.plan = Number(row[c.p])    || 0
      this.past = Number(row[c.past]) || 0
    },

    fmt(val, type) {
      if (val == null) return '—'
      if (type === 'amount') {
        if (Math.abs(val) >= 1_000_000)
          return (val / 1_000_000).toFixed(2).replace('.', ',') + '\u00a0' + this.$t('common.mln')
        if (Math.abs(val) >= 1_000)
          return (val / 1_000).toFixed(1).replace('.', ',') + '\u00a0' + this.$t('common.tys')
        // Малые числа (конверсия, количество позиций, кредит%) — 2 знака после запятой
        return Number(val).toFixed(2).replace('.', ',')
      }
      return Number(val).toLocaleString('ru-RU')
    },

    initTrendChart() {
      if (!this.$refs.trendCanvas || !this.trendData.labels.length) return
      this.destroyTrendChart()

      // данные уже идут от старого к новому — не переворачиваем
      const {labels, facts, plans} = this.trendData
      const color = this.theme.strokeDark
      const t = this.$t.bind(this)
      const fmtFn = (v) => this.fmt(v, this.cfg.fmt)

      this._trendChart = markRaw(new Chart(this.$refs.trendCanvas.getContext('2d'), {
        type: 'line',
        data: {
          labels,
          datasets: [
            {
              label: t('common.fact'),
              data: facts,
              borderColor: color,
              backgroundColor: color + '18',
              borderWidth: 2.5,
              pointBackgroundColor: color,
              pointBorderColor: '#fff',
              pointBorderWidth: 2.5,
              pointRadius: 5,
              pointHoverRadius: 7,
              tension: 0.4,
              fill: true,
            },
            {
              label: t('common.plan'),
              data: plans,
              borderColor: '#94a3b8',
              backgroundColor: 'transparent',
              borderWidth: 2,
              borderDash: [6, 4],
              pointBackgroundColor: '#94a3b8',
              pointBorderColor: '#fff',
              pointBorderWidth: 2,
              pointRadius: 4,
              pointHoverRadius: 6,
              tension: 0.4,
              fill: false,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: {duration: 400},
          interaction: {mode: 'index', intersect: false},
          layout: {padding: {top: 10, right: 10}},

          plugins: {
            legend: {display: false},
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.92)',
              titleColor: '#e2e8f0',
              bodyColor: '#94a3b8',
              borderColor: 'rgba(255,255,255,0.08)',
              borderWidth: 1,
              padding: 12,
              cornerRadius: 10,
              callbacks: {
                label(ctx) {
                  return `  ${ctx.dataset.label}: ${fmtFn(ctx.parsed.y)}`
                },
              },
            },
          },

          scales: {
            x: {
              grid: {display: false},
              border: {display: false},
              ticks: {
                color: '#64748b',
                font: {size: 11, weight: '500'},
                maxRotation: 30,
              },
            },
            y: {
              grid: {color: 'rgba(148,163,184,0.12)'},
              border: {display: false},
              ticks: {
                color: '#64748b',
                font: {size: 11},
                callback: (v) => fmtFn(v),
              },
            },
          },
        },
      }))
    },

    destroyTrendChart() {
      if (this._trendChart) {
        this._trendChart.destroy();
        this._trendChart = null
      }
    },
  },
}
</script>

