<template>
  <div class="spc-card">
    <div class="spc-header">
      <div class="spc-tag">{{ $t('supProd.tag') }}</div>
      <h2 class="spc-title">{{ chartTitle || $t('supProd.chartTitle') }}</h2>
      <p class="spc-sub">{{ period }}</p>
    </div>

    <div class="spc-legend">
      <div v-for="s in SERIES" :key="s.key" class="spc-leg-item">
        <span class="spc-leg-dot" :style="{ background: s.color }"></span>
        {{ $t(s.labelKey) }}
      </div>
    </div>

    <div class="spc-chart-wrap" :style="{ height: chartHeight + 'px' }">
      <canvas ref="chartCanvas"></canvas>
    </div>
  </div>
</template>

<script>
import { markRaw } from 'vue'
import { Chart, registerables } from 'chart.js'

Chart.register(...registerables)

const SERIES = [
  { key: 'smart',    labelKey: 'supProd.smart',   color: '#6366f1' },
  { key: 'note',     labelKey: 'supProd.note',    color: '#f59e0b' },
  { key: 'tv',       labelKey: 'supProd.tv',      color: '#14b8a6' },
  { key: 'sup_prod', labelKey: 'supProd.supProd', color: '#22c55e' },
  { key: 'poslug',   labelKey: 'supProd.poslug',  color: '#ec4899' },
]

// Подписи над/рядом с барами
function makeLabelPlugin(horizontal) {
  return {
    id: 'supProdLabels',
    afterDatasetsDraw(chart) {
      const { ctx } = chart
      chart.data.datasets.forEach((dataset, di) => {
        const meta = chart.getDatasetMeta(di)
        if (meta.hidden) return
        meta.data.forEach((bar, i) => {
          const val = Number(dataset.data[i] ?? 0)
          if (val < 0.3) return
          const text = val.toFixed(1).replace('.', ',') + '%'
          ctx.save()
          ctx.font = 'bold 8px system-ui'
          ctx.fillStyle = '#334155'
          if (horizontal) {
            // Справа от бара
            ctx.textAlign    = 'left'
            ctx.textBaseline = 'middle'
            ctx.fillText(text, bar.x + 3, bar.y)
          } else {
            // Над баром
            ctx.textAlign    = 'center'
            ctx.textBaseline = 'bottom'
            ctx.fillText(text, bar.x, bar.y - 2)
          }
          ctx.restore()
        })
      })
    },
  }
}

export default {
  name: 'SupProdChart',

  props: {
    items:      { type: Array,   default: () => [] },
    chartTitle: { type: String,  default: '' },
    period:     { type: String,  default: '' },
    horizontal: { type: Boolean, default: false },  // true → горизонтальные бары
  },

  data() {
    return { SERIES }
  },

  computed: {
    // Высота чарта: для горизонтального растёт с количеством магазинов
    chartHeight() {
      if (!this.horizontal) return 320
      return Math.max(300, this.items.length * 72)
    },
  },

  created() { this._chart = null },

  mounted() { this.initChart() },

  beforeUnmount() {
    if (this._chart) { this._chart.destroy(); this._chart = null }
  },

  watch: {
    items: {
      handler() { this.$nextTick(() => this.refreshChart()) },
      deep: true,
    },
  },

  methods: {
    computeMax() {
      if (!this.items.length) return 30
      const allVals = this.items.flatMap(m => SERIES.map(s => Number(m[s.key] ?? 0)))
      return Math.ceil(Math.max(...allVals, 0) + 10)
    },

    initChart() {
      if (!this.$refs.chartCanvas) return
      const t   = this.$t.bind(this)
      const ctx = this.$refs.chartCanvas.getContext('2d')
      const hz  = this.horizontal

      const valueAxisConfig = {
        min:    0,
        max:    this.computeMax(),
        grid:   { color: 'rgba(148,163,184,0.12)' },
        border: { display: false },
        ticks:  { color: '#64748b', font: { size: 10 }, callback: v => v + '%' },
      }

      const labelAxisConfig = {
        grid:   { color: 'rgba(148,163,184,0.15)', drawTicks: false },
        border: { display: false },
        ticks:  { color: '#475569', font: { size: hz ? 11 : 12, weight: '600' }, padding: 8 },
      }

      this._chart = markRaw(new Chart(ctx, {
        type: 'bar',
        data: {
          labels:   [],
          datasets: SERIES.map(s => ({
            label:           t(s.labelKey),
            data:            [],
            backgroundColor: s.color + 'cc',
            borderColor:     s.color,
            borderWidth:     1.5,
            borderRadius:    4,
            borderSkipped:   false,
            barThickness:    hz ? 10 : undefined,  // фиксированная толщина для горизонтальных
          })),
        },
        options: {
          indexAxis:           hz ? 'y' : 'x',
          responsive:          true,
          maintainAspectRatio: false,
          animation:           { duration: 500 },
          interaction:         { mode: 'index', intersect: false },
          layout:              { padding: hz ? { right: 38 } : { top: 20 } },

          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.92)',
              titleColor:      '#e2e8f0',
              bodyColor:       '#94a3b8',
              borderColor:     'rgba(255,255,255,0.08)',
              borderWidth:     1,
              padding:         12,
              cornerRadius:    10,
              callbacks: {
                label(ctx) {
                  const val = Number(ctx.parsed[hz ? 'x' : 'y'] ?? 0)
                  return `  ${ctx.dataset.label}: ${val.toFixed(1).replace('.', ',')}%`
                },
              },
            },
          },

          scales: hz
              ? { x: valueAxisConfig, y: labelAxisConfig }
              : { y: valueAxisConfig, x: labelAxisConfig },
        },
        plugins: [makeLabelPlugin(hz)],
      }))

      this.refreshChart()
    },

    refreshChart() {
      if (!this._chart || !this.items.length) return

      const ds = this._chart.data
      ds.labels = this.items.map(m => m.name)
      SERIES.forEach((s, i) => {
        ds.datasets[i].data = this.items.map(m => Number(m[s.key] ?? 0))
      })

      // Обновляем max оси значений
      const maxKey = this.horizontal ? 'x' : 'y'
      this._chart.options.scales[maxKey].max = this.computeMax()

      this._chart.update('active')
    },
  },
}
</script>

